public void testWritableMap_1_oe() {
    final Map<String, String> map = SplitMapUtils.writableMap(transformedMap);
    attemptGetOperation(new Runnable() {
        @Override
        public void run() {
            map.get(null);
        }
    });
    attemptGetOperation(new Runnable() {
        @Override
        public void run() {
            map.entrySet();
        }
    });
    attemptGetOperation(new Runnable() {
        @Override
        public void run() {
            map.keySet();
        }
    });
    attemptGetOperation(new Runnable() {
        @Override
        public void run() {
            map.values();
        }
    });
    attemptGetOperation(new Runnable() {
        @Override
        public void run() {
            map.size();
        }
    });
    attemptGetOperation(new Runnable() {
        @Override
        public void run() {
            map.isEmpty();
        }
    });
    attemptGetOperation(new Runnable() {
        @Override
        public void run() {
            map.containsKey(null);
        }
    });
    attemptGetOperation(new Runnable() {
        @Override
        public void run() {
            map.containsValue(null);
        }
    });
    attemptGetOperation(new Runnable() {
        @Override
        public void run() {
            map.remove(null);
        }
    });

    // equals, hashcode
    final Map<String, String> other = SplitMapUtils.writableMap(transformedMap);
    assertEquals(other, map);
}

