@Test
public void instantiateFactoryComplex_1_oe() {
    TimeZone.setDefault(TimeZone.getTimeZone("GMT"));
    // 2nd Jan 1970
    final Factory<Date> factory = FactoryUtils.instantiateFactory(Date.class,
        new Class[] {Integer.TYPE, Integer.TYPE, Integer.TYPE},
        new Object[] {Integer.valueOf(70), Integer.valueOf(0), Integer.valueOf(2)});
    assertNotNull(factory);
}

@Test
public void instantiateFactoryComplex_2_oe() {
    TimeZone.setDefault(TimeZone.getTimeZone("GMT"));
    // 2nd Jan 1970
    final Factory<Date> factory = FactoryUtils.instantiateFactory(Date.class,
        new Class[] {Integer.TYPE, Integer.TYPE, Integer.TYPE},
        new Object[] {Integer.valueOf(70), Integer.valueOf(0), Integer.valueOf(2)});
    // removed other assertion
    final Date created = factory.create();
    // long time of 1 day (== 2nd Jan 1970)
    assertEquals(new Date(1000 * 60 * 60 * 24), created);
}

public void testIterator_1_oe() {
    final Iterator<Integer> iter = createIterator();
    final Iterable<Number> iterable = new IteratorIterable<>(iter);

    // first use
    verifyIteration(iterable);

    // second use
    for (final Number actual : iterable) {
        fail("should not be able to iterate twice");
}
}

