        for (int j = i; j < size; j++) {
            other.add(j);
        }
        final TreeList<Integer> l = new TreeList<>();
        for (int j = 0; j < i; j++) {
            l.add(j);
        }

        l.addAll(other);

        final ListIterator<Integer> it = l.listIterator();
